void* _runtime_map_linked_segment(const char* real_path,
                                         const char* link_path,
                                         size_t shm_size) {
    if (!real_path || !link_path) {
        return NULL;
    }

    for (uint32_t i = 0; i < 3; i++) {
        int link_exists = _file_exists(link_path);
        if (!link_exists) {
            return _safe_malloc(shm_size ? shm_size : 1);
